using System;using System.IO;using System.Collections.Generic;using Bokumyaku.Simulation;
public static class TierBalanceCheck{
public static object Run(){var rows=new List<object>();for(int tier=1;tier<=TierBalance.Count;tier++){double previous=0;for(int wave=1;wave<=RunSimulator.LongRunWaveLimit;wave++){double hp=TierBalance.EnemyBaseHp(tier,wave);if(double.IsNaN(hp)||double.IsInfinity(hp)||hp<=previous)throw new Exception("HP boundary");if(tier==1&&hp!=RunSimulator.BaseHp(wave))throw new Exception("Tier1 drift");previous=hp;}foreach(int wave in new[]{1,30,60,100})rows.Add(new{tier,wave,hp=TierBalance.EnemyBaseHp(tier,wave),crystalMultiplier=TierBalance.Get(tier).CrystalMultiplier});}
if(TierBalance.IsUnlocked(2,new[]{99,0,0})||!TierBalance.IsUnlocked(2,new[]{100,0,0})||TierBalance.IsUnlocked(3,new[]{99,100,0})||!TierBalance.IsUnlocked(3,new[]{100,100,0}))throw new Exception("Unlock boundary");
var report=new{passed=true,tableVersion=TierBalance.TableVersion,hpSamples=300000,maxBossHp=TierBalance.EnemyBaseHp(3,RunSimulator.LongRunWaveLimit)*12,rows,scope="Unintegrated original Tier table, Tier1 exact compatibility and finite monotonic HP through existing cap; unlock99/100 and no skip. No gameplay balance claim."};File.WriteAllText(Path.GetFullPath("../docs/evidence/tier-balance-table.json"),Newtonsoft.Json.JsonConvert.SerializeObject(report,Newtonsoft.Json.Formatting.Indented));return report;}}
